<?php

namespace App\Models;

use Illuminate\Database\Eloquent\Builder;
use Illuminate\Database\Eloquent\Concerns\HasUuids;
use Illuminate\Database\Eloquent\Factories\HasFactory;
use Illuminate\Database\Eloquent\Model;
use Illuminate\Database\Eloquent\Relations\BelongsTo;
use Illuminate\Database\Eloquent\Relations\HasMany;

/**
 * A hall layout document (plan section 7.1), generated by App\Services\HallGenerator
 * and drawn in the hall designer (App\Services\Seating\HallLayoutData). A row
 * with a template_key is a starter hall venues copy (phase 8B); `public` halls
 * show on the venue's directory page.
 */
class HallLayout extends Model
{
    use HasFactory, HasUuids;

    protected $fillable = ['org_id', 'owner_id', 'name', 'layout', 'template_key', 'public'];

    protected $attributes = ['public' => false];

    protected function casts(): array
    {
        return ['layout' => 'array', 'public' => 'boolean'];
    }

    public function isTemplate(): bool
    {
        return $this->template_key !== null;
    }

    /** @param  Builder<HallLayout>  $query */
    public function scopeTemplates(Builder $query): void
    {
        $query->whereNotNull('template_key');
    }

    public function organization(): BelongsTo
    {
        return $this->belongsTo(Organization::class, 'org_id');
    }

    public function owner(): BelongsTo
    {
        return $this->belongsTo(User::class, 'owner_id');
    }

    public function events(): HasMany
    {
        return $this->hasMany(Event::class);
    }
}
